Here is the commit message:
ARM: imx5: add missing put_device() call in
 imx_suspend_alloc_ocram()

if of_find_device_by_node() succeed, imx_suspend_alloc_ocram() doesn't
have a corresponding put_device(). Thus add a jump target to fix the
exception handling for this function implementation.

Fixes: 1579c7b9fe01 ("ARM: imx53: Set DDR pins to high impedance when in suspend to RAM.")
Signed-off-by: yu kuai <yukuai3@huawei.com>
Signed-off-by: Shawn Guo <shawnguo@kernel.org>

Here is the root cause:
The bug was caused by the absence of a corresponding `put_device()` call in the `imx_suspend_alloc_ocram()` function when `of_find_device_by_node()` succeeded. This oversight meant that the device reference was not properly released, leading to potential memory leaks or dangling pointers when the function exited due to an error.

Here is the patch:

 static int __init imx_suspend_alloc_ocram(
 				size_t size,
 				void __iomem **virt_out,
 				phys_addr_t *phys_out)
 {
 	struct device_node *node;
 	struct platform_device *pdev;
 	struct gen_pool *ocram_pool;
 	unsigned long ocram_base;
 	void __iomem *virt;
 	phys_addr_t phys;
 	int ret = 0;

 	/* Copied from imx6: TODO factorize */
 	node = of_find_compatible_node(NULL, NULL, "mmio-sram");
 	if (!node) {
 		pr_warn("%s: failed to find ocram node!\n", __func__);
 		return -ENODEV;
 	}

 	pdev = of_find_device_by_node(node);
 	if (!pdev) {
 		pr_warn("%s: failed to find ocram device!\n", __func__);
 		ret = -ENODEV;
 		goto put_node;
 	}

 	ocram_pool = gen_pool_get(&pdev->dev, NULL);
 	if (!ocram_pool) {
 		pr_warn("%s: ocram pool unavailable!\n", __func__);
 		ret = -ENODEV;
-		goto put_node;
+		goto put_device;
 	}

 	ocram_base = gen_pool_alloc(ocram_pool, size);
 	if (!ocram_base) {
 		pr_warn("%s: unable to alloc ocram!\n", __func__);
 		ret = -ENOMEM;
-		goto put_node;
+		goto put_device;
 	}

 	phys = gen_pool_virt_to_phys(ocram_pool, ocram_base);
 	virt = __arm_ioremap_exec(phys, size, false);
 	if (phys_out)
 		*phys_out = phys;
 	if (virt_out)
 		*virt_out = virt;

+put_device:
+	put_device(&pdev->dev);
 put_node:
 	of_node_put(node);

 	return ret;
 }



